package com.finsight.service; import com.finsight.domain.User; import com.finsight.repository.UserRepository; import org.springframework.stereotype.Service; import org.springframework.security.crypto.password.PasswordEncoder; @Service public class AuthService {final UserRepository users;final PasswordEncoder encoder;public AuthService(UserRepository u,PasswordEncoder e){users=u;encoder=e;}public User authenticate(String email,String password){return users.findByEmail(email).filter(u->encoder.matches(password,u.getPasswordHash())).orElse(null);}}
